// 워크플로우 시작 시간 기록
const startTime = new Date().toISOString();
const dateStr = new Date().toISOString().split('T')[0];

return [{
  json: {
    startTime: startTime,
    date: dateStr,
    status: 'started'
  }
}];

// Execute Crawler 응답의 delta 사용 (파일 읽기 없음)
const resp = $input.item.json;
const delta = resp.delta || { products: [], reviews: [], stats: {} };

const products = Array.isArray(delta.products) ? delta.products : [];
const reviews = Array.isArray(delta.reviews) ? delta.reviews : [];
const rawStats = delta.stats || {};
const stats = {
  newProductCount: rawStats.newProductCount ?? products.length,
  newReviewCount: rawStats.newReviewCount ?? reviews.length,
  totalProducts: rawStats.totalProductsInCategory ?? 0
};
if (typeof $workflow !== 'undefined' && $workflow.staticData != null) {
  $workflow.staticData.stats = stats;
}

return [{
  json: {
    products,
    reviews,
    stats,
    hasNewData: products.length > 0 || reviews.length > 0
  }
}];

// Delta products를 개별 아이템으로 (Upsert용)
const products = $input.item.json.products || [];
return products.map(p => ({
  json: {
    product_no: String(p.product_no),
    product_name: p.product_name || '',
    review_count: Number(p.review_count) || 0,
    short_description: p.short_description || '',
    product_image_url: p.product_image_url || '',
    sales_price: Number(p.sales_price) || 0,
    discounted_price: Number(p.discounted_price) || 0,
    product_notice_notices: typeof p.product_notice_notices === 'string' ? p.product_notice_notices : JSON.stringify(p.product_notice_notices || [])
  }
}));

// Delta reviews를 개별 아이템으로 (Ollama 배치 입력용)
const reviews = $input.item.json.reviews || [];
if (reviews.length === 0) return [];
return reviews.map(r => ({
  json: {
    product_no: String(r.product_no),
    contents: r.contents || '',
    registered_at: r.registeredAt || null,
    review_score: 3
  }
}));

// Ollama 응답에서 JSON 배열 파싱 후 배치 리뷰에 점수 부여
const responseText = $json.content ? $json.content.trim() : '';
const batchData = $('Prepare Batch Prompt').item.json.batchData;
let scores = [];
try {
  const jsonMatch = responseText.match(/\[[\s\S]*\]/);
  if (jsonMatch) {
    const results = JSON.parse(jsonMatch[0]);
    scores = results.sort((a, b) => a.id - b.id).map(r => { const s = r.score || 3; return (s >= 1 && s <= 5) ? s : 3; });
  } else {
    const numbers = responseText.match(/[1-5]/g);
    if (numbers) scores = numbers.map(n => parseInt(n));
  }
} catch (e) {
  const numbers = responseText.match(/[1-5]/g);
  if (numbers) scores = numbers.map(n => parseInt(n));
}
if (scores.length < batchData.length) scores = scores.concat(Array(batchData.length - scores.length).fill(3));
else if (scores.length > batchData.length) scores = scores.slice(0, batchData.length);
return batchData.map((data, idx) => ({
  json: {
    ...data,
    contents: (data.contents || '').replace(/\0/g, '').replace(/[\x00-\x1F\x7F]/g, ' ').trim(),
    review_score: (scores[idx] >= 1 && scores[idx] <= 5) ? scores[idx] : 3
  }
}));

// Delta products로부터 임베딩용 아이템 생성 (initial_embedding.py notice 로직)
function noticeJsonToText(notices) {
  if (!notices || !Array.isArray(notices)) return '';
  const sentences = [];
  for (const item of notices) {
    const title = (item.title || '').trim();
    const desc = (item.description || '').trim();
    if (!title || !desc) continue;
    const cleanTitle = title.replace(/｢화장품법｣에 따라 /g, '').replace(/｢화장품법｣에 따른 /g, '');
    const cleanDesc = desc.replace(/\\n/g, ' ').trim();
    if (title.includes('용량') || title.includes('중량')) sentences.push(`내용물의 용량은 ${cleanDesc}입니다.`);
    else if (title.includes('피부타입') || title.includes('사양')) sentences.push(`${cleanDesc}에 사용 가능한 제품입니다.`);
    else if (title.includes('사용방법')) sentences.push(`사용 방법은 ${cleanDesc}.`);
    else if (title.includes('제조국')) sentences.push(`제조국은 ${cleanDesc}입니다.`);
    else if (title.includes('기능성')) sentences.push(`${cleanDesc} 제품입니다.`);
    else if (title.includes('성분')) { const shortDesc = cleanDesc.length > 200 ? cleanDesc.substring(0, 200) + '...' : cleanDesc; sentences.push(`주요 성분은 ${shortDesc}입니다.`); }
    else if (title.includes('주의사항')) sentences.push(`사용 시 주의사항은 다음과 같습니다. ${cleanDesc}`);
    else sentences.push(`${cleanTitle}은 ${cleanDesc}입니다.`);
  }
  return sentences.join(' ');
}
const products = $input.item.json.products || [];
const out = [];
for (const p of products) {
  let notices = Array.isArray(p.product_notice_notices) ? p.product_notice_notices : [];
  try { if (typeof p.product_notice_notices === 'string') notices = JSON.parse(p.product_notice_notices || '[]'); } catch (e) {}
  const noticeText = noticeJsonToText(notices);
  const embeddingText = `상품명: ${p.product_name || ''}\n설명: ${p.short_description || ''}\n\n${noticeText}`;
  out.push({
    json: {
      id: parseInt(p.product_no),
      text: embeddingText,
      payload: {
        type: 'product',
        product_no: String(p.product_no),
        product_name: p.product_name || '',
        sales_price: p.sales_price || 0,
        discounted_price: p.discounted_price || 0,
        review_count: p.review_count || 0,
        product_image_url: p.product_image_url || '',
        price: (p.discounted_price > 0 ? p.discounted_price : p.sales_price) || 0,
        has_discount: p.discounted_price > 0 && p.discounted_price < (p.sales_price || 0),
        indexed_at: new Date().toISOString()
      }
    }
  });
}
return out;

// 단일 리뷰 아이템(Parse Batch Results 출력)으로부터 임베딩용 1건 생성 (Ollama 평가 점수 반영)
const crypto = require('crypto');
const r = $input.item.json;
const contents = (r.contents || '').trim();
if (!contents) return [];
const productNo = String(r.product_no);
const regAt = r.registered_at != null ? String(r.registered_at) : '';
const hash = crypto.createHash('sha256').update(productNo + regAt + contents).digest('hex').substring(0, 16);
const pointId = 'r_' + hash;
return [{
  json: {
    id: pointId,
    text: contents,
    payload: {
      type: 'review',
      product_no: productNo,
      review_score: (r.review_score >= 1 && r.review_score <= 5) ? r.review_score : 3,
      registered_at: regAt ? regAt.substring(0, 10) : null,
      indexed_at: new Date().toISOString(),
      contents: contents.length <= 500 ? contents : contents.substring(0, 500) + '…'
    }
  }
}];

// Ollama 응답에서 벡터 추출 및 Qdrant 저장 준비
const embeddingResponse = $input.item.json;
const originalData = $('Prepare Product Embeddings').item.json;

if (!embeddingResponse.embeddings || !Array.isArray(embeddingResponse.embeddings) || embeddingResponse.embeddings.length === 0) {
  throw new Error('임베딩 생성 실패: 응답에 벡터가 없습니다.');
}

const vector = embeddingResponse.embeddings[0];

return [{
  json: {
    point_id: originalData.id,
    vector: vector,
    payload: originalData.payload
  }
}];

// Ollama 응답에서 벡터 추출 및 Qdrant 저장 준비
const embeddingResponse = $input.item.json;
const originalData = $('Prepare Review Embeddings').item.json;

if (!embeddingResponse.embeddings || !Array.isArray(embeddingResponse.embeddings) || embeddingResponse.embeddings.length === 0) {
  throw new Error('임베딩 생성 실패: 응답에 벡터가 없습니다.');
}

const vector = embeddingResponse.embeddings[0];

return [{
  json: {
    point_id: originalData.id,
    vector: vector,
    payload: originalData.payload
  }
}];

// Qdrant upsert 형식으로 변환
const pointId = $json.point_id;
const vector = $json.vector;
const payload = $json.payload;

const qdrantPoint = {
  id: pointId,
  vector: vector,
  payload: payload
};

return [{ json: { point: qdrantPoint } }];

// Qdrant upsert 형식으로 변환
const pointId = $json.point_id;
const vector = $json.vector;
const payload = $json.payload;

const qdrantPoint = {
  id: pointId,
  vector: vector,
  payload: payload
};

return [{ json: { point: qdrantPoint } }];

// 임베딩 완료 통계 수집
const stats = $workflow.staticData.stats || { newProductCount: 0, newReviewCount: 0, totalProducts: 0 };
const productResults = $('Upsert Product To Qdrant').all();
const reviewResults = $('Upsert Review To Qdrant').all();

const embeddingStats = {
  productEmbeddingSuccess: productResults.filter(r => !r.json.error).length,
  productEmbeddingFailed: productResults.filter(r => r.json.error).length,
  reviewEmbeddingSuccess: reviewResults.filter(r => !r.json.error).length,
  reviewEmbeddingFailed: reviewResults.filter(r => r.json.error).length
};

return [{
  json: {
    stats: stats,
    ...embeddingStats,
    embeddingComplete: true
  }
}];

